class Solution {
    public List<List<Integer>> mergeRanges(int[][] intervals) {
        List<long[]> ranges = new ArrayList<>();
        for (int[] iv : intervals) ranges.add(new long[]{iv[0], iv[1]});
        boolean merged = true;
        while (merged) {
            merged = false;
            outer:
            for (int i = 0; i < ranges.size(); i++)
                for (int j = i + 1; j < ranges.size(); j++) {
                    long[] p = ranges.get(i), q = ranges.get(j);
                    if (q[0] <= p[1] + 1 && p[0] <= q[1] + 1) {
                        ranges.set(i, new long[]{Math.min(p[0], q[0]), Math.max(p[1], q[1])});
                        ranges.remove(j);
                        merged = true;
                        break outer;
                    }
                }
        }
        ranges.sort((p, q) -> Long.compare(p[0], q[0]));
        List<List<Integer>> out = new ArrayList<>();
        for (long[] r : ranges) out.add(Arrays.asList((int) r[0], (int) r[1]));
        return out;
    }
}

